const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "mysql",
  "inlineSchema": "generator client {\n  provider      = \"prisma-client-js\"\n  binaryTargets = [\"windows\", \"native\", \"debian-openssl-1.0.x\", \"debian-openssl-1.1.x\", \"debian-openssl-3.0.x\", \"rhel-openssl-1.0.x\", \"rhel-openssl-1.1.x\", \"rhel-openssl-3.0.x\"]\n}\n\ndatasource db {\n  provider = \"mysql\"\n}\n\n// ─── HOSPITAL / TENANT ─────────────────────────────────────\n\nmodel Hospital {\n  id           String   @id @default(uuid())\n  name         String\n  slug         String   @unique\n  domain       String?  @unique\n  customDomain String?  @unique\n  email        String?\n  phone        String?\n  address      String?\n  city         String?\n  state        String?\n  country      String?  @default(\"India\")\n  pincode      String?\n  logo         String?\n  banner       String?\n  website      String?\n  description  String?  @db.Text\n  latitude     Float?\n  longitude    Float?\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  users        User[]\n  departments  Department[]\n  doctors      Doctor[]\n  patients     Patient[]\n  appointments Appointment[]\n  queues       Queue[]\n  invoices     Invoice[]\n  medicines    Medicine[]\n  labTests     LabTest[]\n  staff        Staff[]\n  holidays     Holiday[]\n  settings     HospitalSetting[]\n\n  @@map(\"hospitals\")\n}\n\nmodel HospitalSetting {\n  id         String   @id @default(uuid())\n  hospitalId String\n  hospital   Hospital @relation(fields: [hospitalId], references: [id])\n  key        String\n  value      String   @db.Text\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@unique([hospitalId, key])\n  @@map(\"hospital_settings\")\n}\n\n// ─── AUTH / USERS / ROLES / PERMISSIONS ────────────────────\n\nmodel User {\n  id           String    @id @default(uuid())\n  hospitalId   String?\n  hospital     Hospital? @relation(fields: [hospitalId], references: [id])\n  email        String    @unique\n  password     String\n  firstName    String\n  lastName     String\n  phone        String?\n  avatar       String?\n  isActive     Boolean   @default(true)\n  isSuperAdmin Boolean   @default(false)\n  lastLoginAt  DateTime?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  userRoles UserRole[]\n  auditLogs AuditLog[]\n  doctor    Doctor?\n  staff     Staff?\n\n  @@map(\"users\")\n}\n\nmodel Role {\n  id          String   @id @default(uuid())\n  name        String   @unique\n  description String?\n  isSystem    Boolean  @default(false)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  userRoles       UserRole[]\n  rolePermissions RolePermission[]\n\n  @@map(\"roles\")\n}\n\nmodel UserRole {\n  id        String   @id @default(uuid())\n  userId    String\n  roleId    String\n  user      User     @relation(fields: [userId], references: [id])\n  role      Role     @relation(fields: [roleId], references: [id])\n  createdAt DateTime @default(now())\n\n  @@unique([userId, roleId])\n  @@map(\"user_roles\")\n}\n\nmodel Permission {\n  id          String   @id @default(uuid())\n  name        String   @unique\n  module      String\n  action      String\n  description String?\n  createdAt   DateTime @default(now())\n\n  rolePermissions RolePermission[]\n\n  @@map(\"permissions\")\n}\n\nmodel RolePermission {\n  id           String     @id @default(uuid())\n  roleId       String\n  permissionId String\n  role         Role       @relation(fields: [roleId], references: [id])\n  permission   Permission @relation(fields: [permissionId], references: [id])\n  createdAt    DateTime   @default(now())\n\n  @@unique([roleId, permissionId])\n  @@map(\"role_permissions\")\n}\n\n// ─── DEPARTMENTS ───────────────────────────────────────────\n\nmodel Department {\n  id          String   @id @default(uuid())\n  hospitalId  String\n  hospital    Hospital @relation(fields: [hospitalId], references: [id])\n  name        String\n  description String?  @db.Text\n  icon        String?\n  image       String?\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  doctors Doctor[]\n\n  @@map(\"departments\")\n}\n\n// ─── DOCTORS ───────────────────────────────────────────────\n\nmodel Doctor {\n  id                String     @id @default(uuid())\n  hospitalId        String\n  hospital          Hospital   @relation(fields: [hospitalId], references: [id])\n  userId            String?    @unique\n  user              User?      @relation(fields: [userId], references: [id])\n  departmentId      String\n  department        Department @relation(fields: [departmentId], references: [id])\n  firstName         String\n  lastName          String\n  email             String     @unique\n  phone             String?\n  gender            String?\n  dateOfBirth       DateTime?\n  avatar            String?\n  qualification     String?\n  experience        Int        @default(0)\n  specialization    String?\n  bio               String?    @db.Text\n  consultationFee   Decimal    @default(0) @db.Decimal(10, 2)\n  languages         String?\n  rating            Float      @default(0)\n  totalPatients     Int        @default(0)\n  isAvailable       Boolean    @default(true)\n  isOnline          Boolean    @default(false)\n  consultationTypes String?    @default(\"offline,online\")\n  achievements      String?    @db.Text\n  memberships       String?    @db.Text\n  videoConsultUrl   String?\n  createdAt         DateTime   @default(now())\n  updatedAt         DateTime   @updatedAt\n\n  schedules    DoctorSchedule[]\n  vacations    DoctorVacation[]\n  appointments Appointment[]\n  queues       Queue[]\n\n  @@map(\"doctors\")\n}\n\nmodel DoctorSchedule {\n  id           String   @id @default(uuid())\n  doctorId     String\n  doctor       Doctor   @relation(fields: [doctorId], references: [id])\n  dayOfWeek    Int // 0=Sunday, 1=Monday ... 6=Saturday\n  startTime    String // \"09:00\"\n  endTime      String // \"17:00\"\n  slotDuration Int      @default(30) // minutes\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  @@unique([doctorId, dayOfWeek])\n  @@map(\"doctor_schedules\")\n}\n\nmodel DoctorVacation {\n  id         String   @id @default(uuid())\n  doctorId   String\n  doctor     Doctor   @relation(fields: [doctorId], references: [id])\n  startDate  DateTime\n  endDate    DateTime\n  reason     String?\n  isApproved Boolean  @default(false)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@map(\"doctor_vacations\")\n}\n\n// ─── PATIENTS ──────────────────────────────────────────────\n\nmodel Patient {\n  id                       String    @id @default(uuid())\n  hospitalId               String\n  hospital                 Hospital  @relation(fields: [hospitalId], references: [id])\n  userId                   String?\n  firstName                String\n  lastName                 String\n  email                    String?\n  phone                    String\n  gender                   String?\n  dateOfBirth              DateTime?\n  bloodGroup               String?\n  avatar                   String?\n  address                  String?\n  city                     String?\n  state                    String?\n  pincode                  String?\n  nationality              String?\n  aadhaarNumber            String?\n  panNumber                String?\n  emergencyContactName     String?\n  emergencyContactPhone    String?\n  emergencyContactRelation String?\n  insuranceProvider        String?\n  insurancePolicyNumber    String?\n  insuranceExpiry          DateTime?\n  allergies                String?   @db.Text\n  medicalHistory           String?   @db.Text\n  isActive                 Boolean   @default(true)\n  createdAt                DateTime  @default(now())\n  updatedAt                DateTime  @updatedAt\n\n  appointments   Appointment[]\n  medicalRecords MedicalRecord[]\n  invoices       Invoice[]\n  familyMembers  PatientFamilyMember[]\n  documents      PatientDocument[]\n  queueTokens    QueueToken[]\n\n  @@map(\"patients\")\n}\n\nmodel PatientFamilyMember {\n  id           String   @id @default(uuid())\n  patientId    String\n  patient      Patient  @relation(fields: [patientId], references: [id])\n  name         String\n  relationship String\n  phone        String?\n  email        String?\n  isEmergency  Boolean  @default(false)\n  createdAt    DateTime @default(now())\n\n  @@map(\"patient_family_members\")\n}\n\nmodel PatientDocument {\n  id         String   @id @default(uuid())\n  patientId  String\n  patient    Patient  @relation(fields: [patientId], references: [id])\n  title      String\n  fileUrl    String\n  fileType   String\n  uploadedBy String?\n  createdAt  DateTime @default(now())\n\n  @@map(\"patient_documents\")\n}\n\n// ─── APPOINTMENTS ──────────────────────────────────────────\n\nmodel Appointment {\n  id               String   @id @default(uuid())\n  hospitalId       String\n  hospital         Hospital @relation(fields: [hospitalId], references: [id])\n  patientId        String\n  patient          Patient  @relation(fields: [patientId], references: [id])\n  doctorId         String\n  doctor           Doctor   @relation(fields: [doctorId], references: [id])\n  appointmentDate  DateTime\n  startTime        String\n  endTime          String\n  consultationType String   @default(\"offline\") // offline, online, emergency\n  reason           String?  @db.Text\n  status           String   @default(\"scheduled\") // scheduled, confirmed, in_progress, completed, cancelled, no_show\n  cancelReason     String?\n  queueTokenId     String?  @unique\n  notes            String?  @db.Text\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  medicalRecord MedicalRecord?\n  invoice       Invoice?\n  queueToken    QueueToken?\n\n  @@index([hospitalId, appointmentDate])\n  @@index([doctorId, appointmentDate])\n  @@index([patientId])\n  @@map(\"appointments\")\n}\n\n// ─── QUEUE MANAGEMENT ──────────────────────────────────────\n\nmodel Queue {\n  id           String   @id @default(uuid())\n  hospitalId   String\n  hospital     Hospital @relation(fields: [hospitalId], references: [id])\n  doctorId     String\n  doctor       Doctor   @relation(fields: [doctorId], references: [id])\n  date         DateTime @db.Date\n  currentToken Int      @default(0)\n  status       String   @default(\"running\") // running, break, completed, emergency\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  tokens QueueToken[]\n\n  @@unique([doctorId, date])\n  @@map(\"queues\")\n}\n\nmodel QueueToken {\n  id            String       @id @default(uuid())\n  queueId       String\n  queue         Queue        @relation(fields: [queueId], references: [id])\n  patientId     String\n  patient       Patient      @relation(fields: [patientId], references: [id])\n  appointmentId String?      @unique\n  appointment   Appointment? @relation(fields: [appointmentId], references: [id])\n  tokenNumber   Int\n  status        String       @default(\"waiting\") // waiting, serving, completed, cancelled, no_show\n  priority      String       @default(\"normal\") // normal, urgent, emergency\n  estimatedTime Int? // minutes\n  calledAt      DateTime?\n  completedAt   DateTime?\n  createdAt     DateTime     @default(now())\n  updatedAt     DateTime     @updatedAt\n\n  @@map(\"queue_tokens\")\n}\n\n// ─── MEDICAL RECORDS ───────────────────────────────────────\n\nmodel MedicalRecord {\n  id            String       @id @default(uuid())\n  patientId     String\n  patient       Patient      @relation(fields: [patientId], references: [id])\n  appointmentId String?      @unique\n  appointment   Appointment? @relation(fields: [appointmentId], references: [id])\n  hospitalId    String\n  diagnosis     String?      @db.Text\n  symptoms      String?      @db.Text\n  notes         String?      @db.Text\n  vitals        Json? // {temperature, bp, heartRate, weight, height, oxygenSaturation}\n  followUpDate  DateTime?\n  createdAt     DateTime     @default(now())\n  updatedAt     DateTime     @updatedAt\n\n  prescriptions Prescription[]\n  labReports    LabReport[]\n\n  @@index([patientId])\n  @@map(\"medical_records\")\n}\n\nmodel Prescription {\n  id              String        @id @default(uuid())\n  medicalRecordId String\n  medicalRecord   MedicalRecord @relation(fields: [medicalRecordId], references: [id])\n  medicineName    String\n  dosage          String\n  frequency       String\n  duration        String\n  instructions    String?\n  isBeforeFood    Boolean       @default(true)\n  createdAt       DateTime      @default(now())\n\n  @@map(\"prescriptions\")\n}\n\n// ─── LABORATORY ────────────────────────────────────────────\n\nmodel LabTest {\n  id             String   @id @default(uuid())\n  hospitalId     String\n  hospital       Hospital @relation(fields: [hospitalId], references: [id])\n  name           String\n  category       String?\n  description    String?\n  price          Decimal  @db.Decimal(10, 2)\n  turnaroundTime String?\n  isActive       Boolean  @default(true)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  labReports LabReport[]\n\n  @@map(\"lab_tests\")\n}\n\nmodel LabReport {\n  id              String        @id @default(uuid())\n  hospitalId      String\n  medicalRecordId String\n  medicalRecord   MedicalRecord @relation(fields: [medicalRecordId], references: [id])\n  labTestId       String\n  labTest         LabTest       @relation(fields: [labTestId], references: [id])\n  result          String?       @db.Text\n  fileUrl         String?\n  status          String        @default(\"pending\") // pending, processing, completed\n  completedAt     DateTime?\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n\n  @@map(\"lab_reports\")\n}\n\n// ─── BILLING ───────────────────────────────────────────────\n\nmodel Invoice {\n  id            String       @id @default(uuid())\n  hospitalId    String\n  hospital      Hospital     @relation(fields: [hospitalId], references: [id])\n  patientId     String\n  patient       Patient      @relation(fields: [patientId], references: [id])\n  appointmentId String?      @unique\n  appointment   Appointment? @relation(fields: [appointmentId], references: [id])\n  invoiceNumber String       @unique\n  subtotal      Decimal      @db.Decimal(10, 2)\n  taxAmount     Decimal      @default(0) @db.Decimal(10, 2)\n  discount      Decimal      @default(0) @db.Decimal(10, 2)\n  totalAmount   Decimal      @db.Decimal(10, 2)\n  paidAmount    Decimal      @default(0) @db.Decimal(10, 2)\n  status        String       @default(\"pending\") // pending, partial, paid, cancelled, refunded\n  paymentMethod String? // cash, card, upi, online, insurance\n  notes         String?\n  createdAt     DateTime     @default(now())\n  updatedAt     DateTime     @updatedAt\n\n  payments     Payment[]\n  invoiceItems InvoiceItem[]\n\n  @@index([hospitalId, createdAt])\n  @@index([patientId])\n  @@map(\"invoices\")\n}\n\nmodel InvoiceItem {\n  id          String   @id @default(uuid())\n  invoiceId   String\n  invoice     Invoice  @relation(fields: [invoiceId], references: [id])\n  description String\n  quantity    Int      @default(1)\n  unitPrice   Decimal  @db.Decimal(10, 2)\n  total       Decimal  @db.Decimal(10, 2)\n  createdAt   DateTime @default(now())\n\n  @@map(\"invoice_items\")\n}\n\nmodel Payment {\n  id             String   @id @default(uuid())\n  invoiceId      String\n  invoice        Invoice  @relation(fields: [invoiceId], references: [id])\n  amount         Decimal  @db.Decimal(10, 2)\n  paymentMethod  String // cash, card, upi, online, insurance\n  transactionId  String?\n  status         String   @default(\"success\") // pending, success, failed, refunded\n  refundedAmount Decimal? @db.Decimal(10, 2)\n  refundReason   String?\n  paymentDate    DateTime @default(now())\n  createdAt      DateTime @default(now())\n\n  @@map(\"payments\")\n}\n\n// ─── PHARMACY / MEDICINES ──────────────────────────────────\n\nmodel Medicine {\n  id            String    @id @default(uuid())\n  hospitalId    String\n  hospital      Hospital  @relation(fields: [hospitalId], references: [id])\n  name          String\n  genericName   String?\n  category      String?\n  manufacturer  String?\n  unit          String    @default(\"strip\")\n  price         Decimal   @db.Decimal(10, 2)\n  stockQuantity Int       @default(0)\n  minStock      Int       @default(10)\n  expiryDate    DateTime?\n  batchNumber   String?\n  isActive      Boolean   @default(true)\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  @@map(\"medicines\")\n}\n\n// ─── STAFF ─────────────────────────────────────────────────\n\nmodel Staff {\n  id          String    @id @default(uuid())\n  hospitalId  String\n  hospital    Hospital  @relation(fields: [hospitalId], references: [id])\n  userId      String?   @unique\n  user        User?     @relation(fields: [userId], references: [id])\n  employeeId  String    @unique\n  firstName   String\n  lastName    String\n  email       String?\n  phone       String?\n  gender      String?\n  dateOfBirth DateTime?\n  department  String?\n  designation String?\n  joinDate    DateTime?\n  salary      Decimal?  @db.Decimal(10, 2)\n  shift       String? // morning, afternoon, night\n  isActive    Boolean   @default(true)\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  attendance Attendance[]\n  leaves     Leave[]\n\n  @@map(\"staff\")\n}\n\nmodel Attendance {\n  id        String    @id @default(uuid())\n  staffId   String\n  staff     Staff     @relation(fields: [staffId], references: [id])\n  date      DateTime  @db.Date\n  checkIn   DateTime?\n  checkOut  DateTime?\n  status    String    @default(\"present\") // present, absent, half_day, late, on_leave\n  notes     String?\n  createdAt DateTime  @default(now())\n\n  @@unique([staffId, date])\n  @@map(\"attendance\")\n}\n\nmodel Leave {\n  id         String   @id @default(uuid())\n  staffId    String\n  staff      Staff    @relation(fields: [staffId], references: [id])\n  type       String // casual, sick, earned, maternity, paternity, unpaid\n  startDate  DateTime\n  endDate    DateTime\n  reason     String?\n  status     String   @default(\"pending\") // pending, approved, rejected\n  approvedBy String?\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@map(\"leaves\")\n}\n\n// ─── HOLIDAYS ──────────────────────────────────────────────\n\nmodel Holiday {\n  id          String   @id @default(uuid())\n  hospitalId  String\n  hospital    Hospital @relation(fields: [hospitalId], references: [id])\n  name        String\n  date        DateTime @db.Date\n  description String?\n  createdAt   DateTime @default(now())\n\n  @@unique([hospitalId, date])\n  @@map(\"holidays\")\n}\n\n// ─── NOTIFICATIONS ─────────────────────────────────────────\n\nmodel Notification {\n  id        String    @id @default(uuid())\n  userId    String\n  title     String\n  message   String    @db.Text\n  type      String // appointment, payment, system, reminder\n  channel   String? // email, sms, whatsapp, push\n  isRead    Boolean   @default(false)\n  data      Json?\n  sentAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([userId, isRead])\n  @@map(\"notifications\")\n}\n\n// ─── CMS / WEBSITE ─────────────────────────────────────────\n\nmodel CmsPage {\n  id          String   @id @default(uuid())\n  slug        String   @unique\n  title       String\n  content     String   @db.LongText\n  metaTitle   String?\n  metaDesc    String?\n  isPublished Boolean  @default(false)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"cms_pages\")\n}\n\nmodel Blog {\n  id          String    @id @default(uuid())\n  title       String\n  slug        String    @unique\n  content     String    @db.LongText\n  excerpt     String?   @db.Text\n  coverImage  String?\n  author      String?\n  tags        String?\n  category    String?\n  isPublished Boolean   @default(false)\n  publishedAt DateTime?\n  viewCount   Int       @default(0)\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  @@map(\"blogs\")\n}\n\nmodel Faq {\n  id        String   @id @default(uuid())\n  question  String\n  answer    String   @db.Text\n  category  String?\n  sortOrder Int      @default(0)\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"faqs\")\n}\n\nmodel Testimonial {\n  id            String   @id @default(uuid())\n  patientName   String\n  patientAvatar String?\n  rating        Int      @default(5)\n  content       String   @db.Text\n  isPublished   Boolean  @default(false)\n  createdAt     DateTime @default(now())\n\n  @@map(\"testimonials\")\n}\n\nmodel Gallery {\n  id        String   @id @default(uuid())\n  title     String?\n  fileUrl   String\n  fileType  String // image, video\n  category  String?\n  sortOrder Int      @default(0)\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  @@map(\"gallery\")\n}\n\nmodel ContactMessage {\n  id        String    @id @default(uuid())\n  name      String\n  email     String\n  phone     String?\n  subject   String?\n  message   String    @db.Text\n  isRead    Boolean   @default(false)\n  repliedAt DateTime?\n  createdAt DateTime  @default(now())\n\n  @@map(\"contact_messages\")\n}\n\n// ─── AUDIT LOGS ────────────────────────────────────────────\n\nmodel AuditLog {\n  id        String   @id @default(uuid())\n  userId    String?\n  user      User?    @relation(fields: [userId], references: [id])\n  action    String // CREATE, UPDATE, DELETE\n  module    String // patient, appointment, billing, etc.\n  entityId  String?\n  oldData   Json?\n  newData   Json?\n  ipAddress String?\n  userAgent String?\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@index([module, createdAt])\n  @@map(\"audit_logs\")\n}\n"
}

